parts.text:
{
  "units": [
    {
      "quote": "Invented public-display permit policy. This is a diagnostic document, not legal guidance.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Provides the document title and disclaims legal guidance, serving as diagnostic background without imposing or conferring any substantive duties, permissions, prohibitions, or rules to retain."
    },
    {
      "quote": "(a) For a temporary display open to the public after sunset on agency premises, the organizer must satisfy all of the following conditions:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "If a temporary display on agency premises is open to the public after sunset, the organizer is obligated to satisfy all four cumulative conditions set forth in paragraphs (1) through (4)."
    },
    {
      "quote": "(1) The organizer must illuminate every public exit throughout the time the display remains open.",
      "scope_quotes": [
        "(a) For a temporary display open to the public after sunset on agency premises, the organizer must satisfy all of the following conditions:"
      ],
      "kind": "requirement",
      "meaning": "For a temporary display open to the public after sunset on agency premises, the organizer must continuously illuminate every public exit throughout the entire time the display remains open."
    },
    {
      "quote": "(2) The organizer must keep every public exit clear throughout the time the display remains open.",
      "scope_quotes": [
        "(a) For a temporary display open to the public after sunset on agency premises, the organizer must satisfy all of the following conditions:"
      ],
      "kind": "requirement",
      "meaning": "For a temporary display open to the public after sunset on agency premises, the organizer must keep every public exit clear and unobstructed throughout the entire time the display remains open."
    },
    {
      "quote": "Equipment stored behind a locked staff-only door is not an obstruction of a public exit.",
      "scope_quotes": [
        "(a) For a temporary display open to the public after sunset on agency premises, the organizer must satisfy all of the following conditions:",
        "(2) The organizer must keep every public exit clear throughout the time the display remains open."
      ],
      "kind": "definition",
      "meaning": "Under the exit-clearance requirement for an after-sunset public display on agency premises, equipment stored behind a locked staff-only door is legally defined as not constituting an obstruction of a public exit."
    },
    {
      "quote": "(3) The organizer must appoint an adult steward who remains on site throughout the time the display remains open.",
      "scope_quotes": [
        "(a) For a temporary display open to the public after sunset on agency premises, the organizer must satisfy all of the following conditions:"
      ],
      "kind": "requirement",
      "meaning": "For a temporary display open to the public after sunset on agency premises, the organizer is required to appoint an adult steward who must remain physically on site for the entire duration that the display remains open."
    },
    {
      "quote": "This appointment duty does not apply when an agency employee is assigned to supervise the display for that entire period.",
      "scope_quotes": [
        "(a) For a temporary display open to the public after sunset on agency premises, the organizer must satisfy all of the following conditions:",
        "(3) The organizer must appoint an adult steward who remains on site throughout the time the display remains open."
      ],
      "kind": "exemption",
      "meaning": "For a temporary display open to the public after sunset on agency premises, the organizer is exempt from the requirement to appoint an adult steward if an agency employee is assigned to supervise the display for that entire period."
    },
    {
      "quote": "(4) Before admitting the first visitor, the organizer must give the agency either a signed paper inspection record or an electronic inspection record signed by the inspecting officer.",
      "scope_quotes": [
        "(a) For a temporary display open to the public after sunset on agency premises, the organizer must satisfy all of the following conditions:"
      ],
      "kind": "requirement",
      "meaning": "For a temporary display open to the public after sunset on agency premises, before admitting the first visitor, the organizer is required to submit an inspection record to the agency, which must be either a signed paper inspection record or an electronic inspection record signed by the inspecting officer."
    },
    {
      "quote": "either a signed paper inspection record or an electronic inspection record signed by the inspecting officer",
      "scope_quotes": [
        "(a) For a temporary display open to the public after sunset on agency premises, the organizer must satisfy all of the following conditions:",
        "(4) Before admitting the first visitor, the organizer must give the agency either a signed paper inspection record or an electronic inspection record signed by the inspecting officer."
      ],
      "kind": "alternative",
      "meaning": "When fulfilling the pre-admission inspection record mandate for an after-sunset public display on agency premises, the organizer has the alternative choice of providing either a signed paper inspection record or an electronic inspection record signed by the inspecting officer."
    },
    {
      "quote": "Each record must identify the display, the inspection date, and every public exit inspected.",
      "scope_quotes": [
        "(a) For a temporary display open to the public after sunset on agency premises, the organizer must satisfy all of the following conditions:",
        "(4) Before admitting the first visitor, the organizer must give the agency either a signed paper inspection record or an electronic inspection record signed by the inspecting officer."
      ],
      "kind": "requirement",
      "meaning": "For a temporary display open to the public after sunset on agency premises, each inspection record submitted prior to admitting visitors must identify the display, the inspection date, and every public exit inspected."
    },
    {
      "quote": "(b) When a storm warning is active, the organizer must suspend outdoor demonstrations unless all of the following conditions are met:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Whenever a storm warning is active, the organizer is mandated to suspend outdoor demonstrations unless all three of the cumulative conditions in paragraphs (1), (2), and (3) are met."
    },
    {
      "quote": "(1) The demonstration takes place beneath a fixed roof.",
      "scope_quotes": [
        "(b) When a storm warning is active, the organizer must suspend outdoor demonstrations unless all of the following conditions are met:"
      ],
      "kind": "condition",
      "meaning": "When a storm warning is active, an outdoor demonstration is permitted without suspension only if, as the first of three cumulative conditions, it takes place beneath a fixed roof."
    },
    {
      "quote": "(2) The agency has measured wind speed below 20 kilometers per hour at the demonstration site within the preceding 10 minutes.",
      "scope_quotes": [
        "(b) When a storm warning is active, the organizer must suspend outdoor demonstrations unless all of the following conditions are met:"
      ],
      "kind": "threshold",
      "meaning": "When a storm warning is active, an outdoor demonstration is permitted without suspension only if, as the second of three cumulative conditions, the agency has measured wind speed strictly below the threshold of 20 kilometers per hour at the demonstration site within the preceding 10 minutes."
    },
    {
      "quote": "(3) An agency officer authorizes the demonstration for the duration of the current warning.",
      "scope_quotes": [
        "(b) When a storm warning is active, the organizer must suspend outdoor demonstrations unless all of the following conditions are met:"
      ],
      "kind": "condition",
      "meaning": "When a storm warning is active, an outdoor demonstration is permitted without suspension only if, as the third of three cumulative conditions, an agency officer affirmatively authorizes the demonstration for the duration of the current storm warning."
    },
    {
      "quote": "The authorization expires when that warning ends; it does not authorize demonstrations under a later warning.",
      "scope_quotes": [
        "(b) When a storm warning is active, the organizer must suspend outdoor demonstrations unless all of the following conditions are met:",
        "(3) An agency officer authorizes the demonstration for the duration of the current warning."
      ],
      "kind": "prohibition",
      "meaning": "An officer's authorization for an outdoor demonstration during an active storm warning terminates automatically upon the conclusion of that warning, and it is prohibited from authorizing demonstrations under any subsequent or later warning."
    },
    {
      "quote": "(c) For displays held entirely before sunset, the organizer should place a readable map near the entrance.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "When a display is conducted entirely before sunset, the organizer is recommended (should) to place a readable map near the entrance."
    },
    {
      "quote": "This recommendation does not create a duty to illuminate exits after sunset.",
      "scope_quotes": [
        "(c) For displays held entirely before sunset, the organizer should place a readable map near the entrance."
      ],
      "kind": "statement",
      "meaning": "The advisory recommendation to place a readable map near the entrance for daytime displays held entirely before sunset does not establish any legal obligation to illuminate exits after sunset."
    },
    {
      "quote": "(d) The organizer must retain each inspection record for at least 30 calendar days after the display closes.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The organizer is required to retain each inspection record for a minimum threshold duration of at least 30 calendar days after the display closes."
    },
    {
      "quote": "Weekends and holidays count toward the 30 days.",
      "scope_quotes": [
        "(d) The organizer must retain each inspection record for at least 30 calendar days after the display closes."
      ],
      "kind": "definition",
      "meaning": "For calculating the required 30-calendar-day retention period following the closure of a display, weekends and holidays are defined as counting toward the 30-day requirement."
    },
    {
      "quote": "If an investigation is open when that period ends, the organizer must retain the record until the agency closes the investigation.",
      "scope_quotes": [
        "(d) The organizer must retain each inspection record for at least 30 calendar days after the display closes."
      ],
      "kind": "requirement",
      "meaning": "If an agency investigation remains open at the expiration of the 30-calendar-day retention period after display closure, the organizer is obligated to continue retaining the inspection record until the agency officially closes that investigation."
    },
    {
      "quote": "(e) Visitors are not required to supply their home addresses.",
      "scope_quotes": [],
      "kind": "exemption",
      "meaning": "Visitors have no legal obligation to provide their home addresses and are entirely exempt from supplying them."
    },
    {
      "quote": "This policy does not prohibit visitors from bringing paper maps,",
      "scope_quotes": [],
      "kind": "permission",
      "meaning": "Under this policy, visitors are permitted to bring paper maps, as the policy itself contains no prohibition against them."
    },
    {
      "quote": "but other premises rules may restrict particular materials.",
      "scope_quotes": [
        "This policy does not prohibit visitors from bringing paper maps,"
      ],
      "kind": "exception",
      "meaning": "As an exception or caveat to the permission allowing paper maps under this policy, other premises rules remain applicable and may independently restrict particular materials."
    },
    {
      "quote": "A queue may form when several groups arrive together.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Describes a potential physical occurrence regarding queuing when multiple groups arrive simultaneously, conveying no substantive duty, permission, recommendation, prohibition, condition, or threshold to retain."
    }
  ]
}
